const chunks = <T,>(items: T[], size: number): T[][] => {
  const result: T[][] = [];
  for (let index = 0; index < items.length; index += size) result.push(items.slice(index, index + size));
  return result;
};

const renderSparkline = (values: number[]) => {
  const valid = values.filter((value) => Number.isFinite(value) && value > 0);
  if (valid.length === 0) return '<span class="no-trend">No valid MBW trend</span>';
  const width = 78;
  const height = 24;
  const minimum = Math.min(...valid);
  const maximum = Math.max(...valid);
  const range = maximum - minimum || 1;
  const points = valid.map((value, index) => {
    const x = valid.length === 1 ? width / 2 : (index / (valid.length - 1)) * width;
    const y = height - 3 - (((value - minimum) / range) * (height - 6));
    return `${x.toFixed(1)},${y.toFixed(1)}`;
  }).join(' ');
  return `<svg class="sparkline" viewBox="0 0 ${width} ${height}" role="img" aria-label="Recent MBW movement"><polyline points="${points}" fill="none" stroke="#0F4C75" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
};

const reviewTone = (value: number, good: number, watch: number, lowerIsBetter = false) => {
  if (value <= 0) return { label: 'No data', tone: 'neutral' };
  if (lowerIsBetter) {
    if (value <= good) return { label: 'Strong', tone: 'good' };
    if (value <= watch) return { label: 'Watch', tone: 'watch' };
    return { label: 'Review', tone: 'bad' };
  }
  if (value >= good) return { label: 'Strong', tone: 'good' };
  if (value >= watch) return { label: 'Watch', tone: 'watch' };
  return { label: 'Review', tone: 'bad' };
};

